var calc_output = [];

var age = parseFloat(age);
var sldh = parseFloat(sldh);
var uldh = parseFloat(uldh);
var b2m = parseFloat(b2m);
// var hgb= parseFloat(hgb);
var wbc = parseFloat(wbc);
if (UOMSYSTEM == false) { // US units
    var hgb = hgb / 10;
}

// LDH ratio
var ldh_ratio = sldh / uldh;

// Truncate variables
var age60 = (age > 0 && age < 60) ? 60 : (age > 90 ? 90 : age);
var age75 = Math.min(15, Math.max(0, age - 75));

ldh_ratio = (ldh_ratio >= 5) ? 5 : ((ldh_ratio > 0 && ldh_ratio <= 0.5) ? 0.5 : ldh_ratio);
// hgb = (hgb >= 17) ? 17 : ((hgb > 0 && hgb <= 8) ? 8 : hgb);
b2m = (b2m >= 10) ? 10 : ((b2m > 0 && b2m < 1) ? 1 : b2m);
wbc = (wbc >= 11) ? 11 : ((wbc > 0 && wbc < 4) ? 4 : wbc);


var sum = 0.5 * (-0.561)
    + age60 * 0.01
    + age75 * 0.038
    + ldh_ratio * 0.364
    + b2m * 0.159
    + hgb * (-0.081)
    + wbc * 0.075;

var diff = sum - 0.431;
var surv24 = Math.pow(0.89, Math.exp(diff));
var flipi24 = 1 - surv24;

var evt = flipi24 * 100;

var risk, surv;
if (flipi24 <= 0.1) {
    risk = 'Low';
    surv = '98';
} else if (flipi24 > 0.1 && flipi24 <= 0.15) {
    risk = 'Intermediate';
    surv = '92';
} else if (flipi24 > 0.15) {
    risk = 'High';
    surv = '75';
}

calc_output.push({
    name: 'mini',
    value: evt.toFixed(0),
    value_text: '%',
    message: 'Event within 24 months'
});    
calc_output.push({
    name: '10668_FLIPI24_result',
    value: flipi24.toFixed(2),
    value_text: '',
    message: 'FLIPI24<br/><br/>Event within 24 months: ' + evt.toFixed(0) + '%'
});
calc_output.push({
    name: '10668_FLIPI24_interpretation',
    value: risk,
    value_text: 'risk',
    message: '5-year overall survival: ' + surv + '%'
});
